/// An entity named by identity (§15.3, D23). Tag 0 none (a and b zero); tag 1 an existing entity, a = its serial (not 0), b zero; tag 2 a creation id: a = the seq of an earlier action by the same player, b = the index among the entities it created
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd)]
pub struct EntityRef {
    pub a: u32,
    pub b: u16,
    pub tag: EntityRefTag,
}

impl EntityRef {
    /// The encoded size in bytes.
    pub const SIZE: usize = 8;
    pub const OFFSET_A: usize = 0;
    pub const OFFSET_B: usize = 4;
    pub const OFFSET_TAG: usize = 6;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}a"), i128::from(self.a));
        d.int(&format!("{prefix}b"), i128::from(self.b));
        d.int(&format!("{prefix}tag"), i128::from(self.tag.value()));
    }
}

impl Default for EntityRef {
    fn default() -> Self {
        Self { a: 0, b: 0, tag: EntityRefTag::default() }
    }
}
impl EntityRef {
    /// Tag 0 has a and b zero; tag 1 names a serial (not 0) with b zero; tag 2 is a creation id (§15.3).
    pub const fn is_well_formed(&self) -> bool {
        match self.tag {
            EntityRefTag::None => self.a == 0 && self.b == 0,
            EntityRefTag::Serial => self.a != 0 && self.b == 0,
            EntityRefTag::Creation => true,
        }
    }
}

impl Fixed for EntityRef {
    const SIZE: usize = 8;
    fn read(r: &mut Reader<'_>, _field: &'static str) -> DResult<Self> {
        let start = r.pos();
        let f_a = r.u32("EntityRef.a")?;
        let f_b = r.u16("EntityRef.b")?;
        let f_tag = EntityRefTag::read(r, "EntityRef.tag")?;
        r.zeros(1, "EntityRef.reserved")?;
        let v = Self { a: f_a, b: f_b, tag: f_tag };
        if !v.is_well_formed() {
            return Err(r.err_at(start, ErrorKind::BadRef, "EntityRef"));
        }
        Ok(v)
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        if !self.is_well_formed() {
            return Err(enc_err(ErrorKind::BadRef, "EntityRef"));
        }
        w.u32(self.a);
        w.u16(self.b);
        self.tag.write(w, "EntityRef.tag")?;
        w.zeros(1);
        Ok(())
    }
}

