/// items.tags
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(transparent)]
pub struct ItemTags(u16);

impl ItemTags {
    pub const RAW: Self = Self(1 << 0);
    pub const INTERMEDIATE: Self = Self(1 << 1);
    pub const SCIENCE_PACK: Self = Self(1 << 2);
    pub const BUILDING: Self = Self(1 << 3);
    pub const FLUID: Self = Self(1 << 4);
    pub const FUEL: Self = Self(1 << 5);
    pub const MODULE: Self = Self(1 << 6);
    pub const AMMO: Self = Self(1 << 7);
    pub const FINAL: Self = Self(1 << 8);
    pub const EQUIPMENT: Self = Self(1 << 9);
    pub const ARMOR: Self = Self(1 << 10);
    pub const INSTALLED: Self = Self(1 << 11);
    pub const STAFF: Self = Self(1 << 12);
    /// Every declared bit.
    pub const ALL: Self = Self(8191);
    /// No bits.
    pub const EMPTY: Self = Self(0);

    pub const fn bits(self) -> u16 {
        self.0
    }
    /// The flags with these bits, if every bit is declared.
    pub const fn from_bits(v: u16) -> Option<Self> {
        if v & !Self::ALL.0 == 0 { Some(Self(v)) } else { None }
    }
    /// The flags with these bits, declared or not (tests and fixtures; decoders refuse undeclared bits).
    pub const fn from_bits_retain(v: u16) -> Self {
        Self(v)
    }
    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }
    pub const fn difference(self, other: Self) -> Self {
        Self(self.0 & !other.0)
    }
    /// These flags with `other` set or cleared.
    pub const fn with(self, other: Self, on: bool) -> Self {
        if on { self.union(other) } else { self.difference(other) }
    }
}

impl core::ops::BitOr for ItemTags {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        self.union(rhs)
    }
}

